package com.ianblk.zianmobs;
import java.util.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.world.inventory.*;
import net.minecraft.util.RandomSource;
final class TitanEnchantmentSmoke {
 private static void check(boolean ok,String reason){if(!ok)throw new IllegalStateException(reason);}
 static void run(ServerPlayer p){var registry=p.registryAccess().registryOrThrow(Registries.ENCHANTMENT);var items=new LinkedHashMap<String,Item>();CompanionContent.ARMOR.forEach((id,item)->items.put(id,item.get()));CompanionContent.EXTRAS.forEach((id,item)->items.put(id,item.get()));for(var entry:items.entrySet()){var stack=entry.getValue().getDefaultInstance();var expected=new ArrayList<net.minecraft.resources.ResourceKey<Enchantment>>(List.of(Enchantments.UNBREAKING,Enchantments.MENDING));if(entry.getValue() instanceof ArmorItem)expected.add(Enchantments.PROTECTION);if(entry.getValue() instanceof SwordItem){expected.add(Enchantments.SHARPNESS);expected.add(Enchantments.FIRE_ASPECT);expected.add(Enchantments.LOOTING);}if(entry.getKey().equals("titan_helmet")){expected.add(Enchantments.RESPIRATION);expected.add(Enchantments.AQUA_AFFINITY);}if(entry.getKey().equals("titan_boots")){expected.add(Enchantments.FEATHER_FALLING);expected.add(Enchantments.DEPTH_STRIDER);}for(var key:expected){var enchantment=registry.getHolderOrThrow(key);check(stack.supportsEnchantment(enchantment),"Unsupported native enchantment "+entry.getKey()+" "+key);var menu=new AnvilMenu(0,p.getInventory());try{var book=new ItemStack(Items.ENCHANTED_BOOK);book.enchant(enchantment,1);menu.getSlot(0).set(stack.copy());menu.getSlot(1).set(book);menu.createResult();var result=menu.getSlot(2).getItem();check(!result.isEmpty()&&result.getEnchantmentLevel(enchantment)==1,"Anvil rejected Titan book "+entry.getKey()+" "+key);}finally{menu.getSlot(0).set(ItemStack.EMPTY);menu.getSlot(1).set(ItemStack.EMPTY);menu.getSlot(2).set(ItemStack.EMPTY);}}
 var offers=EnchantmentHelper.selectEnchantment(RandomSource.create(27),stack.copy(),30,registry.holders().filter(h->h.is(net.minecraft.tags.EnchantmentTags.IN_ENCHANTING_TABLE)).map(h->(net.minecraft.core.Holder<Enchantment>)h));check(!offers.isEmpty(),"Enchanting table offers no enchantments for "+entry.getKey());if(entry.getValue() instanceof ShieldItem){check(!stack.supportsEnchantment(registry.getHolderOrThrow(Enchantments.SHARPNESS))&&!stack.supportsEnchantment(registry.getHolderOrThrow(Enchantments.PROTECTION)),"Gauntlet accepts incompatible weapon or armor enchantments");}}
 var guest=new ServerPlayer(p.server,p.serverLevel(),new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"ZianGuestSmoke"),net.minecraft.server.level.ClientInformation.createDefault());var source=guest.createCommandSourceStack().withPermission(0);var dispatcher=p.server.getCommands().getDispatcher();for(String name:CompanionPublicAccess.ROOTS){var parsed=dispatcher.parse(name,source);check(!parsed.getReader().canRead()&&parsed.getContext().getCommand()!=null&&dispatcher.getRoot().getChild(name).canUse(source),"Public collection command inaccessible without OP: "+name);}var nested=dispatcher.parse("zianmobs companions",source);check(!nested.getReader().canRead()&&nested.getContext().getCommand()!=null,"Nested companion command needs OP");for(String admin:List.of("reload","mob","zone","loot"))check(!dispatcher.getRoot().getChild("zianmobs").getChild(admin).canUse(source),"Public companion access exposed admin command "+admin);check(!Companions.current.snapshot(guest,"companions","","").get("admin").getAsBoolean(),"Regular player sees admin companion controls");boolean rejected=false;try{Companions.current.snapshot(guest,"companion_access","","");}catch(IllegalArgumentException expected){rejected=true;}check(rejected,"Regular player opened companion grants");
 }
 private TitanEnchantmentSmoke(){}
}
